style.css:
@-moz-document domain("vinted.fr"), domain("vinted.de"), domain("vinted.com"), domain("vinted.co.uk"), domain("vinted.es"), domain("vinted.it"), domain("vinted.nl"), domain("vinted.be"), domain("vinted.pl"), domain("vinted.cz"), domain("vinted.sk"), domain("vinted.at"), domain("vinted.lt"), domain("vinted.lu"), domain("vinted.pt"), domain("vinted.ro"), domain("vinted.hu"), domain("vinted.se"), domain("vinted.fi"), domain("vinted.dk"), domain("vinted.gr"), domain("vinted.hr"), domain("vinted.ie"), domain("vinted.si"), domain("vinted.ee"), domain("vinted.lv"), domain("vinted.bg") {
/* ============================================================
     Vinted Dark
     Vinted's UI is built on a design-token system: CSS custom
     properties stored as raw "r,g,b" triplets and consumed via
     rgb(var(--token)) / rgba(var(--token), a). Remapping the
     greyscale ramp + the semantic background/foreground/stroke
     tokens reskins almost the entire web_ui component library in
     one place. Element-level rules below mop up the handful of
     hardcoded/utility surfaces that don't read a token.
     ============================================================ */

  :root {
    color-scheme: dark !important;

    /* ---- Greyscale ramp (light original -> dark) ---- */
    --greyscale-level-1: 230, 237, 243;   /* primary text (was 21,25,26)  */
    --greyscale-level-2: 156, 167, 176;   /* muted text   (was 90,101,102) */
    --greyscale-level-3: 124, 134, 144;   /* secondary / chip outline      */
    --greyscale-level-4: 38, 44, 51;      /* dividers / light borders       */
    --greyscale-level-5: 20, 24, 29;      /* page background (was 237,242,242) */
    --greyscale-level-6: 28, 33, 40;      /* elevated white surface          */
    --greyscale-level-7: 13, 17, 23;      /* deepest white surface / header  */

    /* ---- Neutral background semantic tokens ---- */
    --background-passive-neutral-elevation-prominent: 28, 33, 40;
    --background-passive-neutral-elevation-subtle:    26, 31, 38;
    --background-passive-neutral-subtle-low:          20, 24, 29;
    --background-passive-neutral-subtle:              42, 49, 57;
    --background-passive-neutral-subtle-high:         156, 167, 176;
    --background-action-neutral-subtle-low-idle:      20, 24, 29;
    --background-action-neutral-subtle-low-hover:     30, 36, 43;
    --background-action-neutral-subtle-low-active:    0, 70, 84;
    --background-action-neutral-subtle-low-selected:  0, 70, 84;
    --background-action-neutral-subtle-idle:          42, 49, 57;
    --background-action-neutral-inverse-idle:         28, 33, 40;
    --background-passive-disabled:                    30, 36, 43;
    --background-passive-neutral-elevation:           28, 33, 40;

    /* ---- Brand teal: keep the hue, lift for dark legibility ---- */
    --primary-default:    51, 173, 184;   /* was 0,119,130 — brighter teal  */
    --primary-medium:     134, 205, 207;
    --primary-light:      18, 54, 61;      /* dark teal tint for fills        */
    --primary-extra-light: 16, 40, 45;
    --primary-dark:       134, 205, 207;   /* text-on-teal contexts go light  */
    --primary-extra-dark: 201, 240, 238;
    --primarylightexperimental: 22, 56, 62;
    --background-action-primary-prominent-idle: 0, 119, 130;
    --background-passive-primary-prominent:     0, 119, 130;
    --background-passive-primary-prominent-high: 0, 95, 105;
    --background-passive-primary-subtle:        18, 54, 61;
    --background-passive-primary-subtle-high:   22, 70, 78;
    --foreground-action-primary-prominent-idle: 51, 173, 184;
    --foreground-action-primary-prominent-high-idle: 134, 205, 207;
    --foreground-passive-primary-prominent:     51, 173, 184;
    --stroke-action-primary-prominent-idle:     0, 119, 130;
    --stroke-passive-primary-prominent:         51, 173, 184;
    --link-parameters-text-color: rgba(51, 173, 184, 1);

    /* ---- Keep semantic status colours readable on dark ---- */
    --background-passive-success-subtle:      20, 40, 30;
    --background-passive-success-subtle-high: 28, 56, 42;
    --background-passive-error-subtle:        46, 24, 27;
    --background-passive-error-subtle-high:   64, 32, 36;
    --background-passive-warning-subtle:      48, 40, 22;
    --background-passive-warning-subtle-high: 64, 52, 28;

    /* ---- Overlay / shadow ---- */
    --background-passive-neutral-overlay: 6, 8, 10;
    --shadow: 0, 0, 0;
  }

  /* ---- Base surfaces ---- */
  html, body { background-color: #14181d !important; color: #e6edf3 !important; }
  .site, #content, #app, .body-content, .container,
  .l-default, .standard-layout, .feed-grid, main {
    background-color: transparent !important; }
  .site { background-color: #14181d !important; }

  /* Utility background helpers (hardcoded white) */
  .u-background-white,
  [class*="u-background-white"] { background-color: #1c2128 !important; }

  /* Page shell <main class="site u-background-white">: Vinted raised the
     specificity of its white-bg rule on a CDN sheet, so the single-class
     overrides above lose and main stays white on catalog/profile. Raise
     specificity to force the base surface (scoped to the main shell only,
     so other u-background-white cards keep their elevated #1c2128). */
  html body main.site.u-background-white,
  html body .standard-layout { background-color: #14181d !important; }

  /* Homepage hero overlay card + seller-promotion card.
     These are CSS-module surfaces painted with a hardcoded white;
     match on the stable class-name prefix (the trailing hash varies). */
  [class*="hero-block"], [class*="hero-block__card"],
  [class*="seller-promotion"], [class*="promotion-block"],
  [class*="homepage-block"] [class*="card"] {
    background-color: #1c2128 !important; }
  [class*="hero-block"] h1, [class*="hero-block"] h2,
  [class*="hero-block"] p, [class*="hero-block"] span,
  [class*="seller-promotion"] h1, [class*="seller-promotion"] h2,
  [class*="seller-promotion"] p, [class*="seller-promotion"] span {
    color: #e6edf3 !important; }

  /* ---- Soften every default light border into a dark line ---- */
  * { border-color: #262c33 !important; }
  /* web_ui buttons encode their identity in `color`: Button__filled fills with
     currentColor, Button__outlined rings with currentColor, and both filled and
     flat are natively border-transparent. The blanket rule above overwrote all
     three — the primary CTA lost its teal ring and every flat icon button grew
     a grey box. Restore the component's own border behaviour. */
  .web_ui__Button__filled, [class*="Button__filled"],
  .web_ui__Button__flat, [class*="Button__flat"] {
    border-color: transparent !important; }
  .web_ui__Button__outlined, [class*="Button__outlined"] {
    border-color: currentColor !important; }
  /* Outlined/flat primary buttons draw ring, label and icon from `color`;
     the raw brand teal is too dark on our surfaces, so lift the whole
     button. Filled primary is untouched — its fill IS this colour. */
  [class*="Button__outlined"][class*="Button__primary"],
  [class*="Button__flat"][class*="Button__primary"] { color: #4db8c4 !important; }

  /* ============================================================
     Header / global nav
     ============================================================ */
  .l-header, .l-header__main, header.l-header, .js-header,
  .l-header__wrapper { background-color: #0d1117 !important; }
  /* The logo is a web_ui Image; the item-photo placeholder fill below would
     otherwise paint a light box behind it on the darker header. */
  .l-header__logo-container [class*="Image__image"],
  .l-header__logo [class*="Image__image"],
  [class*="l-header__logo"] [class*="Image__image"] { background-color: transparent !important; }
  .l-header__main { border-bottom: 1px solid #262c33 !important; }
  .nav-links, .header-nav, [data-testid="nav-tabs"] { background-color: #0d1117 !important; }
  .nav-links a, .header-nav a, [data-testid="nav-tabs"] a,
  .l-header a:not(.web_ui__Button__primary):not([class*="Button__filled"]) { color: #e6edf3 !important; }
  .nav-links a:hover, .header-nav a:hover { color: #9bd4ff !important; }

  /* Category nav bar under the header */
  .catalog-tree-menu, .nav-tabs, .horizontal-navigation,
  [class*="HorizontalScroll"] { background-color: #0d1117 !important; }
  /* The category row is a web_ui Tabs bar, whose surface reads the white
     token (level-6). We map that to the elevated #1c2128, so inside the
     darker header the bar rendered as a lighter floating box with the
     header showing through as slivers at both ends. Pin it to the header
     surface. Tabs elsewhere (profile, item page) stay elevated. */
  .l-header .web_ui__Tabs__tabs,
  .l-header [class*="Tabs__tabs"] { background-color: #0d1117 !important; }

  /* Dropdowns / flyouts / menus */
  .web_ui__Menu__menu, .web_ui__Dropdown__dropdown, .dropdown-menu,
  [class*="Dropdown__content"], [class*="Menu__content"],
  .web_ui__Popover__popover, [role="menu"], [role="listbox"] {
    background-color: #1c2128 !important; }

  /* ============================================================
     Search bar (header)
     ============================================================ */
  .web_ui__InputBar__input-bar, .web_ui__InputBar__value,
  [data-testid="search-text"], [data-testid="search-text--input"],
  .pile, .input-bar {
    background-color: #1c2128 !important; color: #e6edf3 !important; }
  [data-testid="search-text--input"]::placeholder,
  .web_ui__InputBar__value::placeholder,
  input::placeholder, textarea::placeholder { color: #8b949e !important; opacity: 1 !important; }

  /* Search autocomplete: each suggestion wraps the already-typed prefix in
     a <b> painted with the baked muted-grey literal (#5a6566). That reads as
     de-emphasised on the original light dropdown but goes dark-on-dark on our
     dark flyout — lift it to the legible muted grey (still dimmer than the
     white suggestion completion so it still signals "what you typed"). */
  [data-testid="search-suggestion-bg"] b,
  a[data-testid^="suggestion-"] b {
    color: #97a1ab !important; -webkit-text-fill-color: #97a1ab !important; }

  /* ============================================================
     Cells / cards / surfaces (web_ui)
     ============================================================ */
  .web_ui__Cell__cell, .web_ui__Card__card, .web_ui__Card__overflow-auto,
  [class*="Cell__cell"], [class*="Card__card"], .feed-grid__item,
  [data-testid="grid-item"], [data-testid="feed-item"] {
    background-color: #1c2128 !important; }
  .web_ui__Cell__cell.web_ui__Cell__transparent,
  [class*="Cell__transparent"] { background-color: transparent !important; }
  /* Prominent status cells (the green "Vendu"/Sold banner on a sold item,
     plus error/warning notices) are solid-colour web_ui Cells: a saturated
     background carrying white text drawn from greyscale-level-6. The blanket
     Cell rule above flattened the fill to #1c2128 and our level-6 remap
     darkened the label to the same #1c2128 — the banner went invisible
     dark-on-dark. Re-assert a dark-legible status fill and force the label
     light (these variants are solid banners, so every child reads white). */
  [class*="Cell__success"] { background-color: #218056 !important; }
  [class*="Cell__error"], [class*="Cell__danger"] { background-color: #a5343f !important; }
  [class*="Cell__warning"] { background-color: #8a6a1e !important; }
  [class*="Cell__success"], [class*="Cell__success"] *,
  [class*="Cell__error"], [class*="Cell__error"] *,
  [class*="Cell__danger"], [class*="Cell__danger"] *,
  [class*="Cell__warning"], [class*="Cell__warning"] * {
    color: #ffffff !important; fill: #ffffff !important; }

  /* web_ui Text colours are baked as literal light-theme hex inside
     the (cross-origin) component CSS, so the token ramp can't reach
     them — override the variants explicitly. Keep the semantic
     hierarchy: amplified/title = brightest, body/subtitle = primary,
     caption/muted = muted grey, clickable = teal link. */
  .web_ui__Text__amplified, [class*="Text__amplified"],
  .web_ui__Text__title, [class*="Text__title"],
  .web_ui__Text__heading, [class*="Text__heading"] { color: #e6edf3 !important; }
  .web_ui__Text__body, [class*="Text__body"],
  .web_ui__Text__subtitle, [class*="Text__subtitle"] { color: #c4cdd6 !important; }
  .web_ui__Text__caption, [class*="Text__caption"],
  .web_ui__Text__muted, [class*="Text__muted"] { color: #97a1ab !important; }
  /* Teal text links — lift for AA contrast on the dark surfaces */
  .web_ui__Text__clickable, [class*="Text__clickable"] { color: #4db8c4 !important; }
  .web_ui__Text__clickable:hover, [class*="Text__clickable"]:hover { color: #7fd2da !important; }
  /* Text__primary is web_ui's BRAND-teal text variant — the baked literal teal
     is what paints the buyer-protection "X€ incl." total under every item card
     (beside the teal shield glyph) plus other brand-highlighted labels. The
     token ramp can't reach the literal, so the generic subtitle/caption rules
     above flattened it to neutral grey, dropping the highlight and leaving a
     teal shield next to grey text. Restore the lifted link teal. Declared
     after subtitle/caption so it wins the source-order tie on dual-class spans. */
  .web_ui__Text__primary, [class*="Text__primary"] { color: #4db8c4 !important; }

  /* Ghost / outlined / tertiary buttons render teal text on a dark
     surface — lift it for AA. Filled CTAs keep white-on-teal. */
  .web_ui__Button__tertiary .web_ui__Button__label,
  .web_ui__Button__outlined .web_ui__Button__label,
  .web_ui__Button__transparent .web_ui__Button__label,
  a[class*="Button__tertiary"] [class*="Button__label"],
  a[class*="Button__outlined"] [class*="Button__label"] { color: #4db8c4 !important; }
  /* Flat/text buttons (e.g. the search-type "Articles" selector) bake
     a muted grey label — lift it to the primary text colour. A flat
     PRIMARY button ("Ton guide Vinted") is a teal text link, though. */
  .web_ui__Button__flat .web_ui__Button__label,
  [class*="Button__flat"] [class*="Button__label"] { color: #e6edf3 !important; }
  [class*="Button__flat"][class*="Button__primary"]
    [class*="Button__label"] { color: #4db8c4 !important; }
  /* An icon-ONLY flat button (the dismiss X on the shipping-fee banners) has
     no label for the rules above to reach: its glyph is an SVG painted with
     currentColor, and web_ui's neutral button colour is the near-black
     #15191a token — so the X rendered invisible on our dark card. Colour the
     flat button itself. Its background is transparent, so currentColor only
     reaches the label, the icon and the ripple — never a fill. The variant
     rules that this base rule would otherwise swallow are re-asserted below
     (primary is already handled above at a higher specificity). */
  [class*="Button__flat"] { color: #e6edf3 !important; }
  [class*="Button__flat"][class*="Button__success"] { color: #57c98a !important; }
  [class*="Button__flat"][class*="Button__warning"] { color: #f2707a !important; }
  [class*="Button__flat"][class*="Button__muted"] { color: #9ca7b0 !important; }
  /* Filled primary CTA keeps the teal fill — pure white label for AA */
  .web_ui__Button__filled .web_ui__Button__label,
  [class*="Button__filled"] [class*="Button__label"] { color: #ffffff !important; }
  /* An INVERSE filled button is the light pill used on brand/photo surfaces:
     the fill is neutral and the LABEL carries the variant colour (teal /
     green / red / grey). The white rule above flattened all four to white.
     Re-assert the accent, lifted for the dark pill. The pill itself needs
     to sit ABOVE the card it lands on, or it reads as bare text. */
  [class*="Button__inverse"][class*="Button__filled"] {
    background-color: #2a3139 !important;
    border-color: #39424e !important; }
  [class*="Button__inverse"][class*="Button__filled"][class*="Button__primary"]
    [class*="Button__label"] { color: #4db8c4 !important; }
  [class*="Button__inverse"][class*="Button__filled"][class*="Button__success"]
    [class*="Button__label"] { color: #57c98a !important; }
  [class*="Button__inverse"][class*="Button__filled"][class*="Button__warning"]
    [class*="Button__label"] { color: #f2707a !important; }
  [class*="Button__inverse"][class*="Button__filled"][class*="Button__muted"]
    [class*="Button__label"] { color: #9ca7b0 !important; }

  /* The Apple social-login glyph is an SVG <path fill="#000"> baked black, so it
     vanishes on our dark outlined button. Google/Facebook logos are multicolour
     and keep their brand fills — scope the lift to black-filled icon paths only. */
  [class*="Button__icon"] svg path[fill="#000"],
  [class*="Button__icon"] svg path[fill="#000000"],
  [class*="Button__icon"] svg path[fill="black"] { fill: #e6edf3 !important; }

  /* Tabs (seller profile, item page sections) bake the dark literal */
  .web_ui__Tabs__title, [class*="Tabs__title"] { color: #c4cdd6 !important; }
  .web_ui__Tabs__tab--selected .web_ui__Tabs__title,
  [class*="Tabs__tab--selected"] [class*="Tabs__title"] { color: #e6edf3 !important; }

  /* ============================================================
     Item grid (homepage, catalog, search, profile, item page)
     ============================================================ */
  [data-testid="grid-item"], [class*="feed-grid__item"],
  .new-item-box__container, .new-item-box__overlay {
    background-color: transparent !important; }
  .new-item-box__image, .web_ui__Image__image {
    background-color: #1c2128 !important; }
  /* "+N more photos" overlay + status labels baked a light translucent
     scrim with dark text — flip to a dark scrim + light text so it reads
     as an overlay on dark (matches the favourite-heart pill treatment). */
  .web_ui__Image__label, [class*="Image__label"] {
    background-color: rgba(13, 17, 23, 0.6) !important; color: #e6edf3 !important; }
  /* Catalog/search collage tiles paint a "+N more" scrim with
     rgba(var(--greyscale-level-1), .7); we lifted that token to a LIGHT
     value for text, so the scrim turned light and the white "+N" label
     washed out. Force a dark scrim so the white count stays legible. */
  .new-item-box__image-overlay, [class*="image-overlay"] {
    background-color: rgba(13, 17, 23, 0.62) !important; color: #ffffff !important; }

  /* Loading skeletons / placeholders (default light grey) */
  .react-loading-skeleton, [class*="skeleton"],
  [class*="slot-placeholder"], [class*="placeholder--skeleton"] {
    background-color: #232a32 !important;
    background-image: linear-gradient(90deg, #232a32, #2d343d, #232a32) !important; }
  /* react-loading-skeleton animates its shimmer via a ::after pseudo whose
     background-image is a baked light gradient (rgb(225,230,230)→245→225).
     The self-bg override above can't reach it, so a bright band sweeps across
     every skeleton (catalog ad slot, item grid). Repaint the shimmer dark. */
  .react-loading-skeleton::after, [class*="skeleton"]::after {
    background-image: linear-gradient(90deg, #232a32, #2d343d, #232a32) !important; }

  /* Favourite heart button pill on each card */
  [data-testid$="--favourite"], .new-item-box__favourite,
  button[class*="favourite"] { background-color: rgba(13, 17, 23, 0.55) !important; }
  [data-testid="favourite-icon"] svg, [class*="favourite"] svg { color: #e6edf3 !important; }

  /* Price text on cards stays readable */
  [data-testid$="--price-text"], [data-testid="feed-item--price-text"] {
    color: #e6edf3 !important; }

  /* ============================================================
     Catalog filter chips / sidebar
     ============================================================ */
  .web_ui__Chip__chip, [class*="Chip__chip"],
  [data-testid$="-filter--trigger"], [data-testid$="--trigger"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important; }
  .web_ui__Chip__chip:hover, [class*="Chip__chip"]:hover {
    background-color: #232a32 !important; }
  .web_ui__Chip__selected, [class*="Chip__selected"],
  [class*="Chip__chip"][aria-pressed="true"] {
    background-color: #12363d !important; border-color: #1a7d88 !important; }

  /* Pagination — natively the current page is near-black text against
     mid-grey siblings. Our page-link colour was so close to the active
     colour, and the active pill the same #1c2128 as the bar behind it,
     that page 2 of 4 looked identical to pages 1, 3 and 4. Mute the
     siblings and give the current page a genuinely elevated pill. */
  .web_ui__Pagination__pagination a, .web_ui__Pagination__item a,
  [data-testid*="pagination--page-"], [data-testid="catalog-pagination"] a {
    color: #9ca7b0 !important; }
  .web_ui__Pagination__is-active, .web_ui__Pagination__is-active a,
  [data-testid*="pagination--page-"][aria-current="true"] {
    color: #ffffff !important; background-color: #2f3742 !important;
    border-radius: 8px !important; }

  /* ============================================================
     Item page
     ============================================================ */
  .item-sidebar, .item-page, [class*="item-page"],
  [data-testid="item-sidebar-price-container"],
  [data-testid="item-sidebar-pricing-details-container"] {
    background-color: transparent !important; }
  [data-testid="item-shipping-banner"],
  [data-testid="buyer-protection-info-title"] ~ *,
  .item-shipping-banner { background-color: #1c2128 !important; }
  /* The base item price is natively muted grey; lift it to prominent white.
     The buyer-protection TOTAL ("X€ incl.") is natively brand teal (a
     Text__primary span) — leave it to the Text__primary rule above so it
     stays teal here and on every card, instead of flattening to white. */
  [data-testid="item-price"] { color: #e6edf3 !important; }

  /* ============================================================
     Seller / member profile
     ============================================================ */
  .profile, [class*="profile"], [data-testid="profile-username"] {
    background-color: transparent !important; }
  [data-testid="profile-username"] { color: #e6edf3 !important; }
  /* The profile header is not a card: the site lays the username row, the
     seller-badge row and the "about" block out as bare web_ui Cells on a
     page-wide white <main>. Our elevated-surface rules turned each Cell into
     an island, and the badge row — whose two cells do NOT span the full
     width — punched base-coloured holes straight through the header. Native
     renders one flat surface; do the same. Scoped by the header's own
     `.u-flex-grow >` parent, so the review cards and item cards inside
     `.profile__items-wrapper` keep their elevation. */
  .profile .u-flex-grow > [class*="Cell__cell"],
  .profile [class*="u-background-white"],
  .profile [class*="u-background-white"] > [class*="Cell__cell"],
  .profile [class*="Item__item"] [class*="Cell__cell"] {
    background-color: transparent !important; }
  /* Each item card's favourite button is a `u-background-white` pill, so the
     flatten above (specificity 0,2,0) strips it to transparent and the light
     heart floats bare on the photo. Re-assert the dark pill on the profile
     grid — ties the flatten's specificity but wins on source order, and the
     --favourite testid never appears in the header. */
  .profile [data-testid$="--favourite"] {
    background-color: rgba(13, 17, 23, 0.55) !important; }

  /* ============================================================
     Footer
     ============================================================ */
  .main-footer, .l-footer, footer, .main-footer__content {
    background-color: #0d1117 !important; }
  .main-footer a, .l-footer a, footer a { color: #c4cdd6 !important; }
  .main-footer a:hover, footer a:hover { color: #9bd4ff !important; }

  /* ============================================================
     Banners / sticky notices / cookie surrounds
     ============================================================ */
  [data-testid="dismissible-sticky-banner"],
  [data-testid="shipping-fees-applied-banner"],
  .web_ui__Notification__notification, [class*="Banner"] {
    background-color: #1c2128 !important; }

  /* ============================================================
     Ad slots / blank iframes — never let them flash as bright
     rectangles. Darken their containers; leave 3rd-party iframe
     interiors untouched.
     ============================================================ */
  /* `[data-testid*="ad-"]` used to live here and matched the substring in
     "…upl(oad-)button" and "feed-l(oad-)more-button", painting both primary
     teal CTAs the page background. Anchor the match to the start. */
  [id*="ad"][class*="slot"], [class*="ad-slot"],
  [class*="advertisement"], [data-testid^="ad-"], ins,
  [class*="Banner__ad"], div[id^="google_ads"],
  [class*="adunit"], [class*="slot-container"],
  [class*="slot-placeholder"], .slot-info {
    background-color: #14181d !important; }
  /* The ad-slot label ("Publicité") sits over a dark surround */
  .slot-info { color: #8b949e !important; }
  /* Empty / unfilled ad iframes default to dark so they don't flash
     white; loaded third-party creatives keep their own colours. */
  iframe { background-color: #14181d !important; }

  /* ============================================================
     Modals / dialogs / overlays
     ============================================================ */
  .web_ui__Dialog__content, [role="dialog"], .modal__content,
  [class*="Modal__content"], [class*="Dialog__content"] {
    background-color: #1c2128 !important; }

  /* Scrims and the photo lightbox stage are painted with
     rgba(var(--greyscale-level-1), a). That token is near-black in the
     light theme, so we inverted it to a LIGHT value for primary text —
     which flipped the modal scrim to a 48% white wash over the page and
     turned the lightbox letterbox into a full-screen white panel.
     Re-anchor every surface that reads level-1 as a background. */
  .web_ui__Dialog__overlay, [class*="Dialog__overlay"],
  .web_ui__BottomSheet__overlay, [class*="BottomSheet__overlay"] {
    background-color: rgba(6, 8, 10, 0.72) !important; }
  .image-carousel__image-wrapper,
  .complaints-image-carousel__wrapper,
  .complaints-image-carousel__wrapper--phone {
    background-color: #0d1117 !important; }
  .image-carousel__icon-wrapper,
  .complaints-image-carousel__icon-wrapper {
    background-color: rgba(13, 17, 23, 0.55) !important; }
  /* web_ui paints "icon on a dark/photo surface" as Icon__greyscale-level-6,
     i.e. the white-surface token. Inverting that token to an elevated dark
     turned the lightbox close/next/prev glyphs dark-on-dark. Level-6 icons
     only ever sit on photos or scrims, so pin them light. The glyph paths
     carry fill="currentColor", so `color` must be set alongside `fill`. */
  .web_ui__Icon__greyscale-level-6 svg,
  [class*="Icon__greyscale-level-6"] svg {
    fill: #e6edf3 !important; color: #e6edf3 !important; }

  /* CMS-authored help tables (size charts) hardcode an inline light-grey
     header row that goes light-on-light under our text colours. */
  .table-wrapper thead tr, .user-created-content thead tr {
    background-color: #2f3742 !important; }

  /* The 404/error mascot is a <video> with white baked into its frames, so
     no background rule can reach it. Invert it (hue-rotate restores the
     teal laptop and blue collar) and screen the now-black field away. */
  .fullpage-layout video {
    filter: invert(1) hue-rotate(180deg) !important;
    mix-blend-mode: screen !important; }

  /* Inputs / forms / selects in modals & pages */
  input, textarea, select,
  .web_ui__Input__input, [class*="Input__input"] {
    background-color: #1c2128 !important; color: #e6edf3 !important;
    border-color: #2d333b !important; }

  /* ---- OneTrust cookie banner (until accepted) ---- */
  #onetrust-banner-sdk, #onetrust-pc-sdk,
  #onetrust-consent-sdk .ot-sdk-container { background-color: #1c2128 !important; color: #e6edf3 !important; }
  #onetrust-banner-sdk #onetrust-policy-text,
  #onetrust-banner-sdk .ot-b-addl-desc,
  #onetrust-pc-sdk .ot-dpd-desc { color: #c4cdd6 !important; }
  /* TCF2 variant: the inline "N partners" vendor count baked a dark grey
     literal (#4d4d4d) that vanishes on dark — lift it with the body text. */
  #onetrust-banner-sdk .ot-tcf2-vendor-count,
  #onetrust-banner-sdk .ot-text-bold { color: #e6edf3 !important; }
  /* Inline links/handlers (cookie policy, list of partners) bake the raw
     dark teal — lift to the AA link teal used elsewhere. */
  #onetrust-banner-sdk a, #onetrust-pc-sdk a,
  #onetrust-banner-sdk .ot-link-btn,
  #onetrust-banner-sdk .onetrust-vendors-list-handler,
  #onetrust-banner-sdk .ot-cookie-policy-link { color: #4db8c4 !important; }
  /* The secondary "Manage cookies" button bakes a solid-white surface with
     teal text — flip it to a dark elevated pill so it doesn't flash white. */
  #onetrust-pc-btn-handler, #onetrust-banner-sdk .ot-pc-btn-handler {
    background-color: #2a3139 !important; color: #4db8c4 !important;
    border-color: #2d333b !important; }
}
